  "chemistry-5": {
    "kind": "process",
    "caption": "酸鹼、鹽類與中和：推理與檢核流程",
    "steps": [
      "假設酸每 mL 提供的可反應量是鹼的兩倍，混合相同體積仍有酸性成分過量。",
      "因此體積相等不能保證反應量相等。",
      "即使恰好按比例反應，溶液酸鹼性仍需看酸、鹼及生成鹽的性質。"
    ],
    "note": "課堂數值題常另假設強酸強鹼與適當溫度；不可把這些特例推成所有中和反應。"
  },
  "chemistry-6": {
    "kind": "process",
    "caption": "氧化還原、有機物與材料：推理與檢核流程",
    "steps": [
      "鐵生鏽與氧、水等環境條件有關，潮濕提供有利反應環境。",
      "比較時須保持鐵釘材質、表面處理、時間與溫度近似。",
      "若潮濕組較明顯，可支持水分影響鏽蝕的推論，但不能由單次實驗求出所有條件的作用大小。"
    ],
    "note": "鏽蝕是緩慢變化，不必出現火焰；塗層保護作用也須考慮是否完整。"
  },
  "earth-1": {
    "kind": "process",
    "caption": "岩石、板塊與地震：推理與檢核流程",
    "steps": [
      "層理和化石常支持沉積岩來源，可由沉積、堆積及成岩過程解釋。",
      "仍須排除其他形成層狀外觀的原因，並現場辨識材質及構造。",
      "確切年代需化石對比或其他定年資料，不能單憑外觀指定年份。"
    ],
    "note": "岩石分類是形成史的推論，觀察線索可能需要多項互相支持。"
  },
  "earth-2": {
    "kind": "process",
    "caption": "水循環、海洋與地形：推理與檢核流程",
    "steps": [
      "草地土壤通常提供入滲及暫存空間，但仍受土壤含水量影響。",
      "柏油不易滲水，較多雨水可能迅速沿表面流走，增加排水系統負荷。",
      "比較時要控制面積、坡度、雨量與原有含水狀態。"
    ],
    "note": "不能說草地永不淹水；飽和土壤及極端降雨仍可能產生大量逕流。"
  },
  "earth-3": {
    "kind": "process",
    "caption": "天氣、鋒面與臺灣季風：推理與檢核流程",
    "steps": [
      "東北季風可從海上帶來水氣，首先影響東北側。",
      "遇地形抬升，空氣冷卻、凝結，增加降水機會。",
      "西南部部分地區位於背風側，較不易由同一氣流獲得相同雨量。"
    ],
    "note": "這是常見型態而非每日保證；仍須參考當時鋒面、風場與水氣。"
  },
  "earth-4": {
    "kind": "process",
    "caption": "地球運動、四季與月相：推理與檢核流程",
    "steps": [
      "地軸保持近似固定指向，北半球傾向太陽時，太陽高度較高、白晝較長。",
      "同時南半球背向太陽，日照角度與晝長呈相反變化。",
      "兩半球共用幾乎相同的地日距離，卻季節相反，顯示距離不是主要解釋。"
    ],
    "note": "不能把太陽高度較高寫成太陽實際升到地球更近的位置。"
  },
  "earth-5": {
    "kind": "process",
    "caption": "太陽系、星空與尺度：推理與檢核流程",
    "steps": [
      "光年是光在真空一年行進的距離，所以觀測到的光約 20 年前出發。",
      "「20 年」指光的傳播時間，不是現有太空船的旅行時間。",
      "實際旅行還取決於速度、路徑與技術，不能由光年數直接保證。"
    ],
    "note": "這是以距離近似固定的簡化估算；不要把光年當成恆星年齡單位。"
  },
  "earth-6": {
    "kind": "process",
    "caption": "氣候變遷與永續探究：推理與檢核流程",
    "steps": [
      "遮陽棚降低高溫曝曬影響，主要偏向調適。",
      "減少不必要用電，若因此降低相關能源排放，主要偏向減緩。",
      "同一措施也可能兼具效果，例如植樹可遮蔭，但碳效益需按實際生長與維護評估。"
    ],
    "note": "分類不是互斥標籤；要說清楚措施透過什麼機制發揮作用。"
  },
  "biology-7": {
    "kind": "process",
    "caption": "物質進出細胞與酵素催化作用：推理與檢核流程",
    "steps": [
      "唾液中有能作用於澱粉的酵素，適溫組通常能保有活性。",
      "煮沸可能使酵素變性，即使冷卻也不代表原結構一定恢復。",
      "保持澱粉量、唾液量與反應時間一致，再以適當檢測比較。"
    ],
    "note": "不能說所有低溫都會永久破壞酵素；冷與熱的影響機制不同。"
  },
  "biology-8": {
    "kind": "process",
    "caption": "植物的體內運輸與水分恆定：推理與檢核流程",
    "steps": [
      "色水沿部分輸導組織向上到葉，支持莖內存在水的運輸通路。",
      "可切片觀察染色位置，與木質部位置比較。",
      "不能僅此就證明韌皮部不運任何水，或推算所有植物運輸速率相同。"
    ],
    "note": "實驗示範須把觀察與推論分開；染色不等於整個細胞內的所有物質都向上流。"
  },
  "biology-9": {
    "kind": "process",
    "caption": "動物呼吸系統與排泄泌尿作用：推理與檢核流程",
    "steps": [
      "肺泡主要進行氧與 CO₂ 的交換，氧由循環送往細胞。",
      "細胞內的代謝利用養分釋放能量，不能把此過程全歸給肺。",
      "腎形成濾液後會再吸收部分水與有用物質，因此最終尿液與初始濾液不同。"
    ],
    "note": "器官分工要配合流程理解；尿量也不能單獨代表腎功能好壞。"
  },
